<script setup lang="ts">
import {onMounted} from 'vue'
import { type GameSlug } from '#shared/games/progression'
import GameIcon from './GameIcon.vue'
const props=defineProps<{game:GameSlug}>()
const progression=useGameProgress(props.game)
onMounted(()=>progression.init().catch(()=>{}))
</script>
<template><section class="upgrade-bay"><div><h2>Mejora tu equipo</h2><p>Las mejoras se equipan al empezar una nueva partida.</p><strong class="balance"><GameIcon name="coin" :size="18"/> {{progression.coins.value}} monedas {{progression.account.session.value?'de cuenta':'locales'}}</strong><p v-if="!progression.account.session.value">Progreso de invitado en este dispositivo. No se transfiere a la cuenta.</p></div><article v-for="item in progression.catalog" :key="item.key"><div class="upgrade-name"><GameIcon :name="item.key==='barrier'||item.key==='shield'?'shield':'rocket'"/><h3>{{item.name}}</h3></div><p>{{item.description}}</p><div class="levels"><i v-for="level in item.maxLevel" :key="level" :class="{owned:level<=(progression.equipment.value[item.key]||0)}"/><span>Nivel {{progression.equipment.value[item.key]||0}} / {{item.maxLevel}}</span></div><button :disabled="!!progression.busy.value||(progression.equipment.value[item.key]||0)>=item.maxLevel||progression.coins.value<item.price*((progression.equipment.value[item.key]||0)+1)" @click="progression.buy(item.key)">{{(progression.equipment.value[item.key]||0)>=item.maxLevel?'Al máximo':progression.busy.value===item.key?'Equipando…':`${item.price*((progression.equipment.value[item.key]||0)+1)} monedas · Mejorar`}}</button></article><p v-if="progression.error.value" role="alert">{{progression.error.value}}</p></section></template>
